"use client"

import { PdfViewer } from "@/components/ui/pdf-viewer"
import type { ParseResponse } from "@/components/viewers/lib/parse-types"
import { ParseViewer } from "@/components/viewers/parse/parse-viewer"
import parseSample from "@/components/viewers/sample-data/parse.json"

const PDF_URL = "/samples/bank-statement-x4uhhi7t.pdf"

// A parse of the bank-statement sample: per-page, LLM-ready markdown with the
// transactions reconstructed as a table.
const PARSE_RESULT: ParseResponse = {
  output: parseSample.output as ParseResponse["output"],
  usage: parseSample.usage as ParseResponse["usage"],
}

/**
 * Parse viewer block — the source document beside its extracted markdown, kept
 * in sync by page. `ParseViewer` owns the markdown pane (Rendered/Text toggle,
 * page controls); the document surface here is the `PdfViewer`. Scroll the
 * document and the markdown follows; page from the markdown and the document
 * scrolls to match.
 */
export function ParseViewerBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <ParseViewer
        result={PARSE_RESULT}
        renderDocument={(handlers) => (
          <PdfViewer
            source={{
              kind: "url",
              url: PDF_URL,
              fileName: "bank-statement.pdf",
            }}
            bare
            onVisiblePageChange={handlers.onCurrentPageChange}
            onScrollProgressChange={handlers.onScrollProgressChange}
            className="h-full"
          />
        )}
      />
    </div>
  )
}

"use client"

import { type ParseResponse } from "@/components/viewers/lib/parse-types"
import {
  type PageMarkdownDocumentHandlers,
  type PageMarkdownViewerProps,
} from "@/components/viewers/page-markdown/page-markdown-types"
import { PageMarkdownViewer } from "@/components/viewers/page-markdown/page-markdown-viewer"

export type ParseDocumentHandlers = PageMarkdownDocumentHandlers

export interface ParseViewerProps {
  result: ParseResponse | null
  isProcessing?: boolean
  renderDocument?: PageMarkdownViewerProps["renderDocument"]
  onVisiblePageChange?: (pageNumber: number) => void
}

export function ParseViewer({
  result,
  isProcessing = false,
  renderDocument,
  onVisiblePageChange,
}: ParseViewerProps) {
  const pages = result?.output?.pages ?? []
  const text = result?.output?.text ?? undefined
  const resetKey = result?.document?.id

  return (
    <PageMarkdownViewer
      pages={pages}
      text={text}
      isProcessing={isProcessing}
      renderDocument={renderDocument}
      onVisiblePageChange={onVisiblePageChange}
      resetKey={resetKey}
      fileName="parse-output.md"
      processingLabel="Parsing document..."
    />
  )
}

"use client"

import * as React from "react"

import {
  ResizableHandle,
  ResizablePanel,
  ResizablePanelGroup,
} from "@/components/ui/resizable"
import { ViewerBody, ViewerRoot, ViewerSurface } from "@/components/ui/viewer"
import {
  PageMarkdownDocumentPane,
  type PageMarkdownDocumentPaneHandle,
} from "@/components/viewers/page-markdown/page-markdown-document-pane"
import { PageMarkdownEmptyState } from "@/components/viewers/page-markdown/page-markdown-empty-state"
import { PAGE_MARKDOWN_PAGE_WIDTH } from "@/components/viewers/page-markdown/page-markdown-layout"
import { joinMarkdownPages } from "@/components/viewers/page-markdown/page-markdown-model"
import {
  PageMarkdownPane,
  type PageMarkdownPaneHandle,
} from "@/components/viewers/page-markdown/page-markdown-pane"
import {
  usePageMarkdownScale,
  zoomPageScale,
} from "@/components/viewers/page-markdown/page-markdown-scale"
import { usePageMarkdownSync } from "@/components/viewers/page-markdown/page-markdown-sync"
import {
  type PageMarkdownViewerProps,
  type PageMarkdownViewMode,
} from "@/components/viewers/page-markdown/page-markdown-types"

export function PageMarkdownViewer({
  pages,
  text = joinMarkdownPages(pages),
  isProcessing = false,
  renderDocument,
  onVisiblePageChange,
  fileName = "document.md",
  resetKey,
  processingLabel = "Preparing document...",
}: PageMarkdownViewerProps) {
  const hasPages = pages.length > 0
  const [mode, setMode] = React.useState<PageMarkdownViewMode>("rendered")
  const [markdownContainerWidth, setMarkdownContainerWidth] = React.useState<
    number | null
  >(null)
  const pagePaneResetKey = hasPages ? `pages:${resetKey ?? ""}` : "empty"
  const { currentPage, reportDocumentPage, reportMarkdownPage } =
    usePageMarkdownSync({
      onMarkdownPageChange: onVisiblePageChange,
      pageCount: pages.length,
      resetKey: pagePaneResetKey,
    })

  const markdownPaneRef = React.useRef<PageMarkdownPaneHandle | null>(null)
  const documentPaneRef = React.useRef<PageMarkdownDocumentPaneHandle | null>(
    null
  )
  const [documentPageReport, setDocumentPageReport] = React.useState<{
    pageNumber: number
  } | null>(null)

  React.useEffect(() => {
    setMode("rendered")
    setDocumentPageReport(null)
  }, [resetKey])

  const handleDocumentPageChange = React.useCallback(
    (pageNumber: number) => {
      const normalizedPage = Number.isFinite(pageNumber)
        ? Math.floor(pageNumber)
        : 1
      const pageCount = Math.max(1, pages.length)
      setDocumentPageReport({
        pageNumber: Math.min(pageCount, Math.max(1, normalizedPage)),
      })
    },
    [pages.length]
  )
  const handleDocumentScrollProgressChange = React.useCallback(
    (progress: number) => {
      void progress
    },
    []
  )

  React.useEffect(() => {
    if (!documentPageReport) return
    const target = reportDocumentPage(documentPageReport.pageNumber)
    if (target?.pane === "markdown") {
      markdownPaneRef.current?.scrollToPage(target.pageNumber)
    }
  }, [documentPageReport, reportDocumentPage])

  const handleMarkdownPageChange = React.useCallback(
    (pageNumber: number) => {
      const target = reportMarkdownPage(pageNumber)
      if (target?.pane === "document") {
        documentPaneRef.current?.scrollToPage(target.pageNumber)
      }
    },
    [reportMarkdownPage]
  )

  const { fitWidth, scale, setViewerScale } = usePageMarkdownScale({
    containerWidth: markdownContainerWidth,
    pageWidth: PAGE_MARKDOWN_PAGE_WIDTH,
    resetKey,
  })
  const isMarkdownScaleReady = markdownContainerWidth !== null

  if (!hasPages) {
    return (
      <ViewerRoot bare className="h-full flex-1 bg-background">
        <ViewerBody>
          <ViewerSurface>
            <PageMarkdownEmptyState
              isProcessing={isProcessing}
              processingLabel={processingLabel}
            />
          </ViewerSurface>
        </ViewerBody>
      </ViewerRoot>
    )
  }

  const markdownPane = (
    <PageMarkdownPane
      ref={markdownPaneRef}
      pages={pages}
      text={text}
      mode={mode}
      scale={scale}
      isScaleReady={isMarkdownScaleReady}
      currentPage={currentPage}
      fileName={fileName}
      resetKey={resetKey}
      onModeChange={setMode}
      onZoom={(factor) => setViewerScale(zoomPageScale(scale, factor))}
      onFitWidth={fitWidth}
      onContainerWidthChange={setMarkdownContainerWidth}
      onVisiblePageChange={handleMarkdownPageChange}
    />
  )

  if (!renderDocument) {
    return (
      <ViewerRoot bare className="h-full flex-1 bg-background">
        <ViewerBody>
          <ViewerSurface>{markdownPane}</ViewerSurface>
        </ViewerBody>
      </ViewerRoot>
    )
  }

  return (
    <ViewerRoot bare className="h-full flex-1 bg-background">
      <ViewerBody>
        <ResizablePanelGroup
          orientation="horizontal"
          className="min-h-0 flex-1"
        >
          <ResizablePanel defaultSize={52} minSize={28}>
            <ViewerSurface className="h-full">
              <PageMarkdownDocumentPane
                ref={documentPaneRef}
                renderDocument={renderDocument}
                onCurrentPageChange={handleDocumentPageChange}
                onScrollProgressChange={handleDocumentScrollProgressChange}
              />
            </ViewerSurface>
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel defaultSize={48} minSize={28}>
            <ViewerSurface className="h-full">{markdownPane}</ViewerSurface>
          </ResizablePanel>
        </ResizablePanelGroup>
      </ViewerBody>
    </ViewerRoot>
  )
}

"use client"

import * as React from "react"
import { createRoot, type Root } from "react-dom/client"

import { useElementWidth } from "@/hooks/use-element-width"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  createPageMarkdownLayout,
  getPageMarkdownPageLayout,
  getPageMarkdownVisiblePageNumbers,
} from "@/components/viewers/page-markdown/page-markdown-layout"
import {
  usePageMarkdownMeasurements,
  usePageMarkdownScrollAnchor,
} from "@/components/viewers/page-markdown/page-markdown-measurements"
import { PageMarkdownPageFrame } from "@/components/viewers/page-markdown/page-markdown-page-frame"
import { usePageMarkdownScroll } from "@/components/viewers/page-markdown/page-markdown-scroll"
import { PageMarkdownToolbar } from "@/components/viewers/page-markdown/page-markdown-toolbar"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export interface PageMarkdownPaneHandle {
  scrollToPage: (pageNumber: number) => void
}

export const PageMarkdownPane = React.forwardRef<
  PageMarkdownPaneHandle,
  {
    pages: string[]
    text: string
    mode: PageMarkdownViewMode
    scale: number
    isScaleReady: boolean
    currentPage: number
    fileName: string
    resetKey?: string
    onModeChange: (mode: PageMarkdownViewMode) => void
    onZoom: (factor: number) => void
    onFitWidth: () => void
    onContainerWidthChange: (width: number | null) => void
    onVisiblePageChange: (pageNumber: number) => void
  }
>(function PageMarkdownPane(
  {
    pages,
    text,
    mode,
    scale,
    isScaleReady,
    currentPage,
    fileName,
    resetKey,
    onModeChange,
    onZoom,
    onFitWidth,
    onContainerWidthChange,
    onVisiblePageChange,
  },
  ref
) {
  const [viewportWidthRef, viewportWidth] = useElementWidth()
  const canvasRef = React.useRef<HTMLDivElement | null>(null)
  const projectionFrameRef = React.useRef<number | null>(null)
  const projectPagesRef = React.useRef<() => void>(() => {})
  const projectionCacheRef = React.useRef<PageMarkdownProjectionCache>({
    resetKey: null,
    slots: new Map(),
  })
  const pagesSignature = React.useMemo(
    () => `${resetKey ?? ""}\u0000${pages.join("\u0000")}`,
    [pages, resetKey]
  )
  const { measuredHeightByPageNumber, setPageHeight } =
    usePageMarkdownMeasurements({ mode, pages, scale })
  const layout = React.useMemo(
    () =>
      createPageMarkdownLayout({
        measuredHeightByPageNumber,
        mode,
        pages,
        scale,
      }),
    [measuredHeightByPageNumber, mode, pages, scale]
  )
  const {
    handleScroll,
    measureScroll,
    scrollToPage,
    getViewportElement,
    setViewportElement,
    viewportElement,
  } = usePageMarkdownScroll({
    layout,
    onVisiblePageChange,
    pageCount: pages.length,
    resetKey: pagesSignature,
  })

  React.useLayoutEffect(() => {
    onContainerWidthChange(viewportWidth)
  }, [onContainerWidthChange, viewportWidth])

  const { captureScrollAnchor } = usePageMarkdownScrollAnchor({
    layout,
    onRestore: () => projectPagesRef.current(),
    viewportElement,
  })
  const handlePageSize = React.useCallback(
    (pageNumber: number, height: number) => {
      setPageHeight(pageNumber, height, captureScrollAnchor)
    },
    [captureScrollAnchor, setPageHeight]
  )

  const projectPages = React.useCallback(() => {
    projectionFrameRef.current = null
    projectPageMarkdownPages({
      cache: projectionCacheRef.current,
      canvas: canvasRef.current,
      layout,
      mode,
      onSize: handlePageSize,
      pages,
      resetKey: pagesSignature,
      scale,
      viewportElement: getViewportElement(),
    })
  }, [
    getViewportElement,
    handlePageSize,
    layout,
    mode,
    pages,
    pagesSignature,
    scale,
  ])
  React.useLayoutEffect(() => {
    projectPagesRef.current = projectPages
  }, [projectPages])

  const schedulePageProjection = React.useCallback(() => {
    if (projectionFrameRef.current !== null) return
    if (typeof requestAnimationFrame !== "function") {
      projectPages()
      return
    }
    projectionFrameRef.current = requestAnimationFrame(projectPages)
  }, [projectPages])

  React.useImperativeHandle(
    ref ?? null,
    () => ({
      scrollToPage: (pageNumber) => {
        scrollToPage(pageNumber)
        measureScroll()
        projectPages()
      },
    }),
    [measureScroll, projectPages, scrollToPage]
  )

  React.useLayoutEffect(() => {
    projectPages()
  }, [projectPages, viewportElement])

  React.useEffect(
    () => () => {
      if (
        projectionFrameRef.current !== null &&
        typeof cancelAnimationFrame === "function"
      ) {
        cancelAnimationFrame(projectionFrameRef.current)
      }
      disposePageMarkdownProjectionCache(projectionCacheRef.current)
    },
    []
  )

  const handleViewportScroll = React.useCallback(() => {
    handleScroll()
    schedulePageProjection()
  }, [handleScroll, schedulePageProjection])

  const handleViewportKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (
        event.defaultPrevented ||
        event.altKey ||
        event.ctrlKey ||
        event.metaKey
      ) {
        return
      }

      const viewportElement = event.currentTarget
      const maxScrollTop = Math.max(
        0,
        viewportElement.scrollHeight - viewportElement.clientHeight
      )
      let nextScrollTop: number | null = null

      switch (event.key) {
        case "ArrowDown":
          nextScrollTop = viewportElement.scrollTop + 40
          break
        case "ArrowUp":
          nextScrollTop = viewportElement.scrollTop - 40
          break
        case "PageDown":
          nextScrollTop =
            viewportElement.scrollTop + viewportElement.clientHeight * 0.85
          break
        case "PageUp":
          nextScrollTop =
            viewportElement.scrollTop - viewportElement.clientHeight * 0.85
          break
        case "Home":
          nextScrollTop = 0
          break
        case "End":
          nextScrollTop = maxScrollTop
          break
        default:
          return
      }

      event.preventDefault()
      viewportElement.scrollTop = Math.min(
        maxScrollTop,
        Math.max(0, nextScrollTop)
      )
      measureScroll()
      projectPages()
    },
    [measureScroll, projectPages]
  )

  if (!isScaleReady) {
    return (
      <div className="flex h-full min-h-0 min-w-0 flex-col bg-muted/20">
        <div className="h-10 shrink-0 border-b bg-card" />
        <ScrollArea className="min-h-0 flex-1">
          <div ref={viewportWidthRef} className="h-full w-full min-w-0" />
        </ScrollArea>
      </div>
    )
  }

  return (
    <div className="flex h-full min-h-0 min-w-0 flex-col bg-muted/20">
      <PageMarkdownToolbar
        currentPage={Math.min(currentPage, pages.length)}
        pageCount={pages.length}
        mode={mode}
        scale={scale}
        text={text}
        fileName={fileName}
        onModeChange={onModeChange}
        onZoom={onZoom}
        onFitWidth={onFitWidth}
      />
      <ScrollArea
        viewportRef={setViewportElement}
        viewportProps={{
          "aria-label": "Markdown pages",
          onKeyDown: handleViewportKeyDown,
          onScroll: handleViewportScroll,
          tabIndex: 0,
        }}
        className="min-h-0 flex-1"
      >
        <div ref={viewportWidthRef} className="w-full min-w-0">
          <div
            ref={canvasRef}
            className="relative mx-auto"
            style={{
              height: layout.totalHeight,
              minWidth: layout.width,
            }}
          />
        </div>
      </ScrollArea>
    </div>
  )
})

type PageMarkdownProjectionCache = {
  resetKey: unknown
  slots: Map<number, PageMarkdownProjectedSlot>
}

type PageMarkdownProjectedSlot = {
  renderKey: string
  root: Root
  slot: HTMLElement
}

function projectPageMarkdownPages({
  cache,
  canvas,
  layout,
  mode,
  onSize,
  pages,
  resetKey,
  scale,
  viewportElement,
}: {
  cache: PageMarkdownProjectionCache
  canvas: HTMLDivElement | null
  layout: ReturnType<typeof createPageMarkdownLayout>
  mode: PageMarkdownViewMode
  onSize: (pageNumber: number, height: number) => void
  pages: readonly string[]
  resetKey: unknown
  scale: number
  viewportElement: HTMLDivElement | null
}) {
  if (!canvas) return

  canvas.style.height = `${layout.totalHeight}px`
  canvas.style.minWidth = `${layout.width}px`

  if (!Object.is(cache.resetKey, resetKey)) {
    disposePageMarkdownProjectionCache(cache)
    cache.resetKey = resetKey
  }

  const visiblePageNumbers = getPageMarkdownVisiblePageNumbers({
    layout,
    scrollTop: viewportElement?.scrollTop ?? 0,
    viewportHeight: getPageMarkdownViewportHeight(viewportElement),
  })
  const visiblePageNumberSet = new Set(visiblePageNumbers)

  for (const [pageNumber, projectedSlot] of cache.slots) {
    if (visiblePageNumberSet.has(pageNumber)) continue
    disposePageMarkdownProjectedSlot(projectedSlot)
    cache.slots.delete(pageNumber)
  }

  for (const pageNumber of visiblePageNumbers) {
    const pageLayout = getPageMarkdownPageLayout(layout, pageNumber)
    const markdown = pages[pageNumber - 1]
    if (!pageLayout || markdown == null) continue

    const projectedSlot =
      cache.slots.get(pageNumber) ?? createPageMarkdownProjectedSlot(pageNumber)
    patchPageMarkdownProjectedSlot(projectedSlot.slot, pageLayout)
    renderPageMarkdownProjectedSlot({
      markdown,
      mode,
      onSize,
      pageLayout,
      pageNumber,
      projectedSlot,
      scale,
    })
    cache.slots.set(pageNumber, projectedSlot)
    canvas.append(projectedSlot.slot)
  }
}

function createPageMarkdownProjectedSlot(pageNumber: number) {
  const slot = document.createElement("div")
  slot.dataset.pageNumber = String(pageNumber)
  slot.dataset.slot = "page-markdown-page-slot"
  slot.className = "absolute left-1/2 -translate-x-1/2"
  return {
    renderKey: "",
    root: createRoot(slot),
    slot,
  }
}

function patchPageMarkdownProjectedSlot(
  slot: HTMLElement,
  pageLayout: NonNullable<ReturnType<typeof getPageMarkdownPageLayout>>
) {
  slot.style.top = `${pageLayout.offsetTop}px`
  slot.style.width = `${pageLayout.width}px`
  slot.style.minHeight = `${pageLayout.height}px`
}

function renderPageMarkdownProjectedSlot({
  markdown,
  mode,
  onSize,
  pageLayout,
  pageNumber,
  projectedSlot,
  scale,
}: {
  markdown: string
  mode: PageMarkdownViewMode
  onSize: (pageNumber: number, height: number) => void
  pageLayout: NonNullable<ReturnType<typeof getPageMarkdownPageLayout>>
  pageNumber: number
  projectedSlot: PageMarkdownProjectedSlot
  scale: number
}) {
  const renderKey = [
    pageNumber,
    mode,
    scale,
    pageLayout.height,
    pageLayout.width,
    markdown,
  ].join("\u0000")
  if (projectedSlot.renderKey === renderKey) return

  projectedSlot.renderKey = renderKey
  projectedSlot.root.render(
    <PageMarkdownPageFrame
      estimatedHeight={pageLayout.height}
      markdown={markdown}
      mode={mode}
      onSize={onSize}
      pageNumber={pageNumber}
      scale={scale}
    />
  )
}

function getPageMarkdownViewportHeight(viewportElement: HTMLElement | null) {
  return (
    viewportElement?.clientHeight ||
    viewportElement?.getBoundingClientRect().height ||
    0
  )
}

function disposePageMarkdownProjectionCache(cache: PageMarkdownProjectionCache) {
  for (const projectedSlot of cache.slots.values()) {
    disposePageMarkdownProjectedSlot(projectedSlot)
  }
  cache.slots.clear()
}

function disposePageMarkdownProjectedSlot(projectedSlot: PageMarkdownProjectedSlot) {
  deferPageMarkdownRootUnmount(projectedSlot.root)
  projectedSlot.slot.remove()
}

function deferPageMarkdownRootUnmount(root: Root) {
  const unmount = () => root.unmount()
  if (typeof queueMicrotask === "function") {
    queueMicrotask(unmount)
    return
  }
  window.setTimeout(unmount, 0)
}

"use client"

import * as React from "react"

import { scrollDocumentPageIntoView } from "@/components/viewers/page-markdown/page-markdown-document-dom"
import {
  type PageMarkdownDocumentHandlers,
  type PageMarkdownViewerProps,
} from "@/components/viewers/page-markdown/page-markdown-types"

export interface PageMarkdownDocumentPaneHandle {
  scrollToPage: (pageNumber: number) => void
}

export const PageMarkdownDocumentPane = React.forwardRef<
  PageMarkdownDocumentPaneHandle,
  {
    renderDocument: NonNullable<PageMarkdownViewerProps["renderDocument"]>
    onCurrentPageChange: PageMarkdownDocumentHandlers["onCurrentPageChange"]
    onScrollProgressChange: NonNullable<
      PageMarkdownDocumentHandlers["onScrollProgressChange"]
    >
  }
>(function PageMarkdownDocumentPane(
  { renderDocument, onCurrentPageChange, onScrollProgressChange },
  ref
) {
  const documentPaneRef = React.useRef<HTMLDivElement | null>(null)

  React.useImperativeHandle(
    ref ?? null,
    () => ({
      scrollToPage(pageNumber) {
        scrollDocumentPageIntoView(documentPaneRef.current, pageNumber)
      },
    }),
    []
  )

  return (
    <div ref={documentPaneRef} className="h-full min-w-0">
      {renderDocument({ onCurrentPageChange, onScrollProgressChange })}
    </div>
  )
})

export function scrollDocumentPageIntoView(
  root: HTMLElement | null,
  pageNumber: number
): void {
  const target = root?.querySelector<HTMLElement>(
    `[data-page-number="${pageNumber}"]`
  )
  if (typeof target?.scrollIntoView !== "function") return

  target.scrollIntoView({ behavior: "smooth", block: "start" })
}

"use client"

import { ScanText } from "lucide-react"

import { Spinner } from "@/components/ui/spinner"

export function PageMarkdownEmptyState({
  isProcessing,
  processingLabel,
}: {
  isProcessing: boolean
  processingLabel: string
}) {
  return (
    <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-4 bg-muted/30 px-8 text-muted-foreground">
      {isProcessing ? (
        <>
          <Spinner className="size-8 text-primary" />
          <p className="text-sm">{processingLabel}</p>
        </>
      ) : (
        <>
          <ScanText className="size-12 opacity-60" />
          <div className="space-y-1 text-center">
            <p className="text-sm font-medium text-foreground">
              No markdown pages yet
            </p>
            <p className="max-w-xs text-xs">
              Provide page-by-page markdown to see the rendered document here.
            </p>
          </div>
        </>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { Maximize, Minus, Plus } from "lucide-react"

import { useElementWidth } from "@/hooks/use-element-width"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  MarkdownActionButtons,
  MarkdownActionsMenu,
} from "@/components/viewers/page-markdown/page-markdown-actions"
import { PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH } from "@/components/viewers/page-markdown/page-markdown-model"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

export function PageMarkdownToolbar({
  currentPage,
  pageCount,
  mode,
  scale,
  text,
  fileName,
  onModeChange,
  onZoom,
  onFitWidth,
}: {
  currentPage: number
  pageCount: number
  mode: PageMarkdownViewMode
  scale: number
  text: string
  fileName: string
  onModeChange: (mode: PageMarkdownViewMode) => void
  onZoom: (factor: number) => void
  onFitWidth: () => void
}) {
  const [toolbarRef, toolbarWidth] = useElementWidth()
  const isCompact =
    toolbarWidth !== null && toolbarWidth < PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH

  return (
    <div
      ref={toolbarRef}
      className="no-scrollbar flex h-10 shrink-0 items-center gap-1 overflow-x-auto border-b bg-card px-2"
    >
      <div className="flex min-w-0 shrink-0 items-center gap-1">
        <span className="px-1 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
          Page {currentPage} of {pageCount}
        </span>
        <ModeTabs mode={mode} onChange={onModeChange} />
      </div>
      <div className="ml-auto flex shrink-0 items-center gap-1">
        <ToolbarIconButton label="Zoom out" onClick={() => onZoom(1 / 1.2)}>
          <Minus />
        </ToolbarIconButton>
        <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
          {Math.round(scale * 100)}%
        </span>
