import * as React from "react"

import { PAGE_MARKDOWN_PAGE_WIDTH } from "./page-markdown-layout"

export const PAGE_MARKDOWN_SCALE_MIN = 0.35
export const PAGE_MARKDOWN_SCALE_MAX = 3
export const PAGE_MARKDOWN_FIT_SCALE_MAX = 1.5
export const PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING = 32

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

export function clampPageScale(scale: number): number {
  if (!Number.isFinite(scale)) return 1
  return clamp(scale, PAGE_MARKDOWN_SCALE_MIN, PAGE_MARKDOWN_SCALE_MAX)
}

export function fitPageScale(containerWidth: number | null): number {
  if (!containerWidth || !Number.isFinite(containerWidth)) return 1
  return clamp(
    (containerWidth - PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING) /
      PAGE_MARKDOWN_PAGE_WIDTH,
    PAGE_MARKDOWN_SCALE_MIN,
    PAGE_MARKDOWN_FIT_SCALE_MAX
  )
}

export function zoomPageScale(scale: number, factor: number): number {
  return clampPageScale(scale * factor)
}

export function usePageMarkdownScale({
  containerWidth,
  defaultScale,
  onScaleChange,
  pageWidth = PAGE_MARKDOWN_PAGE_WIDTH,
  resetKey,
  scale: controlledScale,
}: {
  containerWidth: number | null
  defaultScale?: number
  onScaleChange?: (scale: number | null) => void
  pageWidth?: number
  resetKey?: string
  scale?: number
}) {
  const normalizedControlledScale = normalizeOptionalPageScale(controlledScale)
  const isScaleControlled = controlledScale != null
  const normalizedDefaultScale = normalizeOptionalPageScale(defaultScale)
  const [manualScale, setManualScale] = React.useState<number | null>(
    normalizedDefaultScale
  )

  React.useEffect(() => {
    setManualScale(normalizedDefaultScale)
  }, [normalizedDefaultScale, resetKey])

  const fitScale =
    containerWidth && Number.isFinite(containerWidth)
      ? clamp(
          (containerWidth - PAGE_MARKDOWN_FIT_HORIZONTAL_PADDING) / pageWidth,
          PAGE_MARKDOWN_SCALE_MIN,
          PAGE_MARKDOWN_FIT_SCALE_MAX
        )
      : 1
  const scale = normalizedControlledScale ?? manualScale ?? fitScale

  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      const normalized =
        nextScale == null ? null : normalizeOptionalPageScale(nextScale)
      if (isScaleControlled) {
        onScaleChange?.(normalized)
        return
      }
      setManualScale(normalized)
      onScaleChange?.(normalized)
    },
    [isScaleControlled, onScaleChange]
  )

  const zoomIn = React.useCallback(() => {
    setViewerScale(zoomPageScale(scale, 1.2))
  }, [scale, setViewerScale])

  const zoomOut = React.useCallback(() => {
    setViewerScale(zoomPageScale(scale, 1 / 1.2))
  }, [scale, setViewerScale])

  const fitWidth = React.useCallback(() => {
    setViewerScale(null)
  }, [setViewerScale])

  return {
    fitWidth,
    scale,
    setViewerScale,
    zoomIn,
    zoomOut,
  }
}

function normalizeOptionalPageScale(scale: number | undefined) {
  return scale == null ? null : clampPageScale(scale)
}

"use client"

import * as React from "react"

import {
  findPageMarkdownPageByOffset,
  getPageMarkdownPageLayout,
  type PageMarkdownLayoutModel,
} from "./page-markdown-layout"
import { clamp } from "./page-markdown-scale"

export function usePageMarkdownScroll({
  layout,
  onScrollProgressChange,
  onVisiblePageChange,
  pageCount,
  resetKey,
}: {
  layout: PageMarkdownLayoutModel
  onScrollProgressChange?: (progress: number) => void
  onVisiblePageChange?: (pageNumber: number) => void
  pageCount: number
  resetKey?: unknown
}) {
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const lastReportedPageNumberRef = React.useRef(0)
  const scrollFrameRef = React.useRef(0)
  const viewportResetKeyRef = React.useRef<unknown>(resetKey)
  const didMountResetEffectRef = React.useRef(false)
  const [viewportElement, setViewportElementState] =
    React.useState<HTMLDivElement | null>(null)
  const [currentPageState, setCurrentPageState] = React.useState<{
    pageNumber: number
    resetKey: unknown
  }>(() => ({ pageNumber: 1, resetKey }))
  const currentPage = Object.is(currentPageState.resetKey, resetKey)
    ? currentPageState.pageNumber
    : 1

  const resetViewportForKey = React.useCallback(
    (element: HTMLDivElement, key: unknown) => {
      viewportResetKeyRef.current = key
      element.scrollTop = 0
      scrollViewportTo(element, 0, { behavior: "auto" })
    },
    []
  )

  const setViewportElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element
      if (element && !Object.is(viewportResetKeyRef.current, resetKey)) {
        resetViewportForKey(element, resetKey)
      }
      setViewportElementState(element)
    },
    [resetKey, resetViewportForKey]
  )

  const measureScroll = React.useCallback(() => {
    scrollFrameRef.current = 0
    const viewportElement = viewportElementRef.current
    if (!viewportElement) return

    const viewportHeight =
      viewportElement.clientHeight ||
      viewportElement.getBoundingClientRect().height
    const scrollable =
      viewportElement.scrollHeight - viewportElement.clientHeight
    const progress =
      scrollable > 0 ? clamp(viewportElement.scrollTop / scrollable, 0, 1) : 0
    onScrollProgressChange?.(progress)

    const markerOffset = viewportElement.scrollTop + viewportHeight * 0.2
    const visiblePageNumber = findPageMarkdownPageByOffset(layout, markerOffset)

    if (
      visiblePageNumber >= 1 &&
      visiblePageNumber <= pageCount &&
      visiblePageNumber !== lastReportedPageNumberRef.current
    ) {
      lastReportedPageNumberRef.current = visiblePageNumber
      setCurrentPageState((previousState) =>
        Object.is(previousState.resetKey, resetKey) &&
        previousState.pageNumber === visiblePageNumber
          ? previousState
          : { pageNumber: visiblePageNumber, resetKey }
      )
      onVisiblePageChange?.(visiblePageNumber)
    }
  }, [layout, onScrollProgressChange, onVisiblePageChange, pageCount, resetKey])
  const measureScrollRef = React.useRef(measureScroll)
  React.useLayoutEffect(() => {
    measureScrollRef.current = measureScroll
  }, [measureScroll])

  const handleScroll = React.useCallback(() => {
    if (scrollFrameRef.current) return
    if (typeof requestAnimationFrame !== "function") {
      measureScrollRef.current()
      return
    }
    scrollFrameRef.current = -1
    const requestedFrame = requestAnimationFrame(() =>
      measureScrollRef.current()
    )
    if (scrollFrameRef.current === -1) {
      scrollFrameRef.current = requestedFrame
    }
  }, [])

  React.useEffect(() => {
    if (!didMountResetEffectRef.current) {
      didMountResetEffectRef.current = true
      return
    }
    lastReportedPageNumberRef.current = 0
    setCurrentPageState((previousState) =>
      Object.is(previousState.resetKey, resetKey) &&
      previousState.pageNumber === 1
        ? previousState
        : { pageNumber: 1, resetKey }
    )
    const viewportElement = viewportElementRef.current
    if (viewportElement) resetViewportForKey(viewportElement, resetKey)
  }, [resetKey, resetViewportForKey])

  const scrollToPage = React.useCallback(
    (pageNumber: number, options?: ScrollToOptions) => {
      const viewportElement = viewportElementRef.current
      if (!viewportElement || pageNumber < 1 || pageNumber > pageCount) return

      const pageLayout = getPageMarkdownPageLayout(layout, pageNumber)
      if (!pageLayout) return

      scrollViewportTo(viewportElement, Math.max(0, pageLayout.offsetTop), {
        behavior: "smooth",
        ...options,
      })
    },
    [layout, pageCount]
  )

  const getViewportElement = React.useCallback(
    () => viewportElementRef.current,
    []
  )

  React.useEffect(() => {
    if (
      scrollFrameRef.current > 0 &&
      typeof cancelAnimationFrame === "function"
    ) {
      cancelAnimationFrame(scrollFrameRef.current)
      scrollFrameRef.current = 0
    }
  }, [measureScroll])

  React.useEffect(
    () => () => {
      if (
        scrollFrameRef.current > 0 &&
        typeof cancelAnimationFrame === "function"
      ) {
        cancelAnimationFrame(scrollFrameRef.current)
      }
    },
    []
  )

  return {
    currentPage,
    getViewportElement,
    handleScroll,
    measureScroll,
    scrollToPage,
    setViewportElement,
    viewportElement,
  }
}

function scrollViewportTo(
  viewportElement: HTMLDivElement,
  top: number,
  options?: ScrollToOptions
) {
  if (typeof viewportElement.scrollTo === "function") {
    viewportElement.scrollTo({ top, ...options })
    return
  }
  viewportElement.scrollTop = top
}

"use client"

import * as React from "react"

import {
  createPageMeasurementKey,
  findPageMarkdownPageByOffset,
  getPageMarkdownPageLayout,
  type PageMarkdownLayoutModel,
} from "@/components/viewers/page-markdown/page-markdown-layout"
import { type PageMarkdownViewMode } from "@/components/viewers/page-markdown/page-markdown-types"

type PageHeightMeasurement = {
  height: number
  measurementKey: string
}

type PageMarkdownScrollAnchor = {
  offsetWithinPage: number
  pageNumber: number
}

export function usePageMarkdownMeasurements({
  mode,
  pages,
  scale,
}: {
  mode: PageMarkdownViewMode
  pages: readonly string[]
  scale: number
}) {
  const [pageHeightMeasurements, setPageHeightMeasurements] = React.useState<
    Map<number, PageHeightMeasurement>
  >(() => new Map())

  const measuredHeightByPageNumber = React.useMemo(() => {
    const measuredHeightByPageNumber = new Map<number, number>()
    for (let pageIndex = 0; pageIndex < pages.length; pageIndex += 1) {
      const pageNumber = pageIndex + 1
      const measurement = pageHeightMeasurements.get(pageNumber)
      if (!measurement) continue

      const measurementKey = createPageMeasurementKey({
        markdown: pages[pageIndex]!,
        mode,
        scale,
      })
      if (measurement.measurementKey === measurementKey) {
        measuredHeightByPageNumber.set(pageNumber, measurement.height)
      }
    }
    return measuredHeightByPageNumber
  }, [mode, pageHeightMeasurements, pages, scale])

  const setPageHeight = React.useCallback(
    (
      pageNumber: number,
      height: number,
      beforeMeasurementChange?: () => void
    ) => {
      const markdown = pages[pageNumber - 1]
      if (!markdown || !Number.isFinite(height) || height <= 0) return

      const measurementKey = createPageMeasurementKey({
        markdown,
        mode,
        scale,
      })
      setPageHeightMeasurements((current) => {
        const currentMeasurement = current.get(pageNumber)
        if (
          currentMeasurement?.measurementKey === measurementKey &&
          currentMeasurement.height === height
        ) {
          return current
        }

        beforeMeasurementChange?.()
        const next = new Map(current)
        next.set(pageNumber, { height, measurementKey })
        return next
      })
    },
    [mode, pages, scale]
  )

  return {
    measuredHeightByPageNumber,
    setPageHeight,
  }
}

export function usePageMarkdownScrollAnchor({
  layout,
  onRestore,
  viewportElement,
}: {
  layout: PageMarkdownLayoutModel
  onRestore?: () => void
  viewportElement: HTMLDivElement | null
}) {
  const pendingScrollAnchorRef = React.useRef<PageMarkdownScrollAnchor | null>(
    null
  )
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)

  React.useLayoutEffect(() => {
    viewportElementRef.current = viewportElement
  }, [viewportElement])

  const captureScrollAnchor = React.useCallback(() => {
    const currentViewportElement = viewportElementRef.current
    if (!currentViewportElement) return

    const pageNumber = findPageMarkdownPageByOffset(
      layout,
      currentViewportElement.scrollTop
    )
    const pageLayout = getPageMarkdownPageLayout(layout, pageNumber)
    if (!pageLayout) return

    pendingScrollAnchorRef.current = {
      offsetWithinPage: currentViewportElement.scrollTop - pageLayout.offsetTop,
      pageNumber,
    }
  }, [layout])

  React.useLayoutEffect(() => {
    const anchor = pendingScrollAnchorRef.current
    const currentViewportElement = viewportElementRef.current
    if (!anchor || !currentViewportElement) return

    pendingScrollAnchorRef.current = null
    const pageLayout = getPageMarkdownPageLayout(layout, anchor.pageNumber)
    if (!pageLayout) return

    currentViewportElement.scrollTop = Math.max(
      0,
      pageLayout.offsetTop + anchor.offsetWithinPage
    )
    onRestore?.()
  }, [layout, onRestore])

  return { captureScrollAnchor }
}

"use client"

import * as React from "react"

export type PageMarkdownSyncPane = "markdown" | "document"

export interface PageMarkdownSyncState {
  pageNumber: number
  pane: PageMarkdownSyncPane
  version: number
}

export interface PendingPageMarkdownScroll {
  pageNumber: number
  pane: PageMarkdownSyncPane
  version: number
}

export interface PageMarkdownSyncTransition {
  confirmed: boolean
  pending: PendingPageMarkdownScroll | null
  scrollTarget: PendingPageMarkdownScroll | null
  state: PageMarkdownSyncState
}

export function initialPageMarkdownSyncState(): PageMarkdownSyncState {
  return { pageNumber: 1, pane: "markdown", version: 0 }
}

export function resolvePageMarkdownSyncReport({
  state,
  pending,
  pane,
  pageNumber,
}: {
  state: PageMarkdownSyncState
  pending: PendingPageMarkdownScroll | null
  pane: PageMarkdownSyncPane
  pageNumber: number
}): PageMarkdownSyncTransition {
  const nextPageNumber = Math.max(
    1,
    Number.isFinite(pageNumber) ? Math.floor(pageNumber) : 1
  )

  if (pending?.pane === pane && pending.pageNumber === nextPageNumber) {
    return {
      confirmed: true,
      pending: null,
      scrollTarget: null,
      state: {
        pageNumber: nextPageNumber,
        pane,
        version: state.version + 1,
      },
    }
  }

  if (pending?.pane === pane) {
    return {
      confirmed: false,
      pending,
      scrollTarget: null,
      state,
    }
  }

  if (!pending && state.pageNumber === nextPageNumber && state.pane === pane) {
    return {
      confirmed: false,
      pending: null,
      scrollTarget: null,
      state,
    }
  }

  if (!pending && state.pageNumber === nextPageNumber) {
    return {
      confirmed: false,
      pending: null,
      scrollTarget: null,
      state: {
        pageNumber: nextPageNumber,
        pane,
        version: state.version + 1,
      },
    }
  }

  const targetPane: PageMarkdownSyncPane =
    pane === "markdown" ? "document" : "markdown"
  const nextState = {
    pageNumber: nextPageNumber,
    pane,
    version: state.version + 1,
  }
  const nextPending = {
    pageNumber: nextPageNumber,
    pane: targetPane,
    version: nextState.version,
  }

  return {
    confirmed: false,
    pending: nextPending,
    scrollTarget: nextPending,
    state: nextState,
  }
}

export function usePageMarkdownSync({
  onMarkdownPageChange,
  pageCount,
  resetKey,
}: {
  onMarkdownPageChange?: (pageNumber: number) => void
  pageCount?: number
  resetKey?: string
}) {
  const [state, setState] = React.useState(initialPageMarkdownSyncState)
  const stateRef = React.useRef(state)
  const pendingRef = React.useRef<PendingPageMarkdownScroll | null>(null)
  const pageCountLimit = Math.max(1, pageCount ?? 1)

  React.useEffect(() => {
    const nextState = initialPageMarkdownSyncState()
    stateRef.current = nextState
    pendingRef.current = null
    setState(nextState)
  }, [resetKey])

  React.useEffect(() => {
    const currentState = stateRef.current
    const nextPageNumber = Math.min(currentState.pageNumber, pageCountLimit)
    const nextState =
      nextPageNumber === currentState.pageNumber
        ? currentState
        : {
            ...currentState,
            pageNumber: nextPageNumber,
            version: currentState.version + 1,
          }
    const currentPending = pendingRef.current

    stateRef.current = nextState
    pendingRef.current =
      currentPending && currentPending.pageNumber <= pageCountLimit
        ? currentPending
        : null
    setState(nextState)
  }, [pageCountLimit])

  React.useEffect(() => {
    stateRef.current = state
  }, [state])

  const reportPage = React.useCallback(
    (pane: PageMarkdownSyncPane, pageNumber: number) => {
      const transition = resolvePageMarkdownSyncReport({
        state: stateRef.current,
        pending: pendingRef.current,
        pane,
        pageNumber,
      })

      stateRef.current = transition.state
      pendingRef.current = transition.pending
      setState(transition.state)

      if (transition.state.pane === "markdown" && !transition.confirmed) {
        onMarkdownPageChange?.(transition.state.pageNumber)
      }

      return transition.scrollTarget
    },
    [onMarkdownPageChange]
  )

  return {
    currentPage: state.pageNumber,
    reportDocumentPage: React.useCallback(
      (pageNumber: number) => reportPage("document", pageNumber),
      [reportPage]
    ),
    reportMarkdownPage: React.useCallback(
      (pageNumber: number) => reportPage("markdown", pageNumber),
      [reportPage]
    ),
  }
}

export const PAGE_MARKDOWN_COMPACT_ACTIONS_WIDTH = 460

export function joinMarkdownPages(pages: string[]): string {
  return pages.join("\n\n")
}

"use client"

import * as React from "react"

export function useElementWidth<T extends HTMLElement = HTMLDivElement>(): [
  React.RefCallback<T>,
  number | null,
] {
  const cleanupRef = React.useRef<(() => void) | null>(null)
  const [width, setWidth] = React.useState<number | null>(null)

  const ref = React.useCallback((element: T | null) => {
    cleanupRef.current?.()
    cleanupRef.current = null

    if (!element) return
    const target = element

    let frame = 0
    let timeout = 0
    let isReadScheduled = false
    let lastReadWidth: number | null = null

    function scheduleRead() {
      if (isReadScheduled) return

      isReadScheduled = true
      const run = () => {
        if (!isReadScheduled) return
        isReadScheduled = false
        if (frame > 0 && typeof cancelAnimationFrame === "function") {
          cancelAnimationFrame(frame)
        }
        if (timeout) window.clearTimeout(timeout)
        frame = 0
        timeout = 0
        readStableWidth()
      }

      timeout = window.setTimeout(run, 50)
      if (typeof requestAnimationFrame !== "function") return

      frame = -1
      const requestedFrame = requestAnimationFrame(run)
      if (frame === -1) frame = requestedFrame
    }

    function readStableWidth() {
      const nextWidth = target.clientWidth
      if (lastReadWidth === nextWidth) {
        setWidth(nextWidth)
        return
      }
      lastReadWidth = nextWidth
      scheduleRead()
    }

    scheduleRead()
    const cleanupScheduledRead = () => {
      if (frame > 0 && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame)
      }
      if (timeout) window.clearTimeout(timeout)
    }
    if (typeof ResizeObserver !== "function") {
      cleanupRef.current = cleanupScheduledRead
      return
    }

    const observer = new ResizeObserver(() => {
      lastReadWidth = null
      scheduleRead()
    })

    observer.observe(element)
    cleanupRef.current = () => {
      cleanupScheduledRead()
      observer.disconnect()
    }
  }, [])

  React.useEffect(() => () => cleanupRef.current?.(), [])

  return [ref, width]
}

// Parse result shape consumed by the parse viewer.

export interface ParseResponse {
  document?: { id?: string; mime_type?: string } | null
  output?: { pages: string[]; text: string } | null
  usage?: { credits: number } | null
}
